using System; using System.Collections.Generic; using System.Linq; using Crownfall.Core; using Crownfall.Stats; using Crownfall.Battle.Grid;
namespace Crownfall.Formation { public enum FormationType{BattleLine,ShieldWall,HunterLine,ArcaneTriangle,Vanguard} [Serializable] public sealed class FormationUnit { public string InstanceId; public GridCoordinate Cell; public bool IsMelee; public bool IsRanged; public bool IsMage; } [Serializable] public sealed class ActiveFormation { public FormationType Type; public List<string> Members=new List<string>(); }
 public sealed class FormationSystem { public List<ActiveFormation> Evaluate(IReadOnlyList<FormationUnit> u){var r=new List<ActiveFormation>();var melee=u.Where(x=>x.IsMelee).ToList();for(int i=0;i<melee.Count;i++)for(int j=i+1;j<melee.Count;j++)if(GridMath.Manhattan(melee[i].Cell,melee[j].Cell)==1)r.Add(new ActiveFormation{Type=FormationType.BattleLine,Members=new List<string>{melee[i].InstanceId,melee[j].InstanceId}}); var ranged=u.Where(x=>x.IsRanged).GroupBy(x=>x.Cell.Y);foreach(var row in ranged)if(row.Count()>=3)r.Add(new ActiveFormation{Type=FormationType.HunterLine,Members=row.Take(3).Select(x=>x.InstanceId).ToList()}); if(melee.Count>=3){foreach(var a in melee) {var group=melee.Where(b=>ConnectedWithin(melee,a,b)).Take(3).ToList();if(group.Count>=3){r.Add(new ActiveFormation{Type=FormationType.ShieldWall,Members=group.Select(x=>x.InstanceId).ToList()});break;}}} foreach(var x in u.Where(x=>x.Cell.Y==0)){if(!u.Any(y=>y.InstanceId!=x.InstanceId&&GridMath.Manhattan(x.Cell,y.Cell)==1))r.Add(new ActiveFormation{Type=FormationType.Vanguard,Members=new List<string>{x.InstanceId}});} return Dedup(r); }
  static bool ConnectedWithin(List<FormationUnit> all,FormationUnit start,FormationUnit target){var q=new Queue<FormationUnit>();var seen=new HashSet<string>();q.Enqueue(start);seen.Add(start.InstanceId);while(q.Count>0){var a=q.Dequeue();if(a.InstanceId==target.InstanceId)return true;foreach(var b in all)if(!seen.Contains(b.InstanceId)&&GridMath.Manhattan(a.Cell,b.Cell)==1){seen.Add(b.InstanceId);q.Enqueue(b);}}return false;} static List<ActiveFormation> Dedup(List<ActiveFormation> x){var seen=new HashSet<string>();return x.Where(f=>seen.Add(f.Type+":"+string.Join(",",f.Members.OrderBy(s=>s)))).ToList();}
  public void ApplySnapshot(IEnumerable<ActiveFormation> active,Dictionary<string,StatModifierSet> stats){foreach(var f in active)foreach(var id in f.Members){if(!stats.TryGetValue(id,out var s))continue;string src="formation:"+f.Type;switch(f.Type){case FormationType.BattleLine:s.AddOrReplace(new StatModifier{Id="armor",Source=src,Stat=StatType.Armor,Operation=ModifierOperation.Flat,Value=10});break;case FormationType.ShieldWall:s.AddOrReplace(new StatModifier{Id="armor",Source=src,Stat=StatType.Armor,Operation=ModifierOperation.Flat,Value=15});break;case FormationType.HunterLine:s.AddOrReplace(new StatModifier{Id="crit",Source=src,Stat=StatType.CritChance,Operation=ModifierOperation.AdditivePercent,Value=.10f});break;case FormationType.Vanguard:s.AddOrReplace(new StatModifier{Id="hp",Source=src,Stat=StatType.MaxHealth,Operation=ModifierOperation.AdditivePercent,Value=.15f});s.AddOrReplace(new StatModifier{Id="tenacity",Source=src,Stat=StatType.Tenacity,Operation=ModifierOperation.AdditivePercent,Value=.20f});break;}}} }
}
